"""Verify only the explicit metadata corrections against the immutable accepted peer checkpoint."""
from pathlib import Path
import datetime,hashlib,json
ROOT=Path.cwd();OUT=ROOT/'docs/evidence/native-body-rj-peer'
def sha(raw):return hashlib.sha256(raw).hexdigest()
def main():
 prior_raw=(OUT/'review.json').read_bytes();prior=json.loads(prior_raw);assert prior['passed'];p=ROOT/'docs/evidence/native-body-rj-em/binding-proposal.json';raw=p.read_bytes();proposal=json.loads(raw);assert sha(raw)=='4f55511f6037bf0bc13666ce9c503abd97695e857aa776f3ca6d3b6f203bfb71';assert proposal['uncoded_items_sha256']==prior['candidate_sha256']==sha((ROOT/proposal['uncoded_items_path']).read_bytes());assert proposal['source_sha256']==prior['source_sha256'];assert proposal['cache_sha256']==prior['cache_sha256'];assert proposal['coded_page_count']==sum(b-a+1 for a,b in proposal['adapter_authority']['coded_learning_ranges'])==238
 old_pairs={(c['old_invalid_id'],c['retained_id'],c['page'],c['code'])for c in prior['EM_supersessions']};new_pairs={(c['invalid_duplicate_id'],c['superseded_by_id'],c['page'],c['code'])for c in proposal['technical_duplicate_supersessions']};assert old_pairs==new_pairs and len(new_pairs)==14
 ledger_path=ROOT/'docs/evidence/native-body-rj-em/technical-supersessions.json';ledger_raw=ledger_path.read_bytes();assert sha(ledger_raw)=='a8accec579520f559be24b91c3927a36357ad7acda6067a0213a2a8c4a00ce8d';ledger=json.loads(ledger_raw);assert ledger['previous_publications_immutable']is True and ledger['pair_count']==14;assert {(c['invalid_duplicate_id'],c['superseded_by_id'],c['page'],c['code'])for c in ledger['pairs']}==old_pairs
 report=json.loads((ROOT/'docs/evidence/native-body-rj-em/recovery-report.json').read_text());proofs={p['invalid_duplicate_id']:p for p in report['technical_duplicate_supersessions']}
 for pair in ledger['pairs']:assert sha(json.dumps(proofs[pair['invalid_duplicate_id']],ensure_ascii=False,sort_keys=True,separators=(',',':')).encode())==pair['proof_sha256']
 efpath=ROOT/prior['EF383']['candidate_path'];efraw=efpath.read_bytes();assert sha(efraw)=='c624bd49f904237c818d08bff8ef1252ec528b88aeb9f6060f1b4720aa57c1be';assert efraw.count(b'eight identifier glyphs')==1;reconstructed=efraw.replace(b'eight identifier glyphs',b'nine identifier glyphs');assert sha(reconstructed)==prior['EF383']['candidate_sha256']=='7451417b3e35dbdf0a3c4e05180680db935d9a071ef90ce37bbae359d493a9e8';assert json.loads(efraw)['items'].__len__()==200
 result={'actor_type':'automated','actor_id':'codex-independent-rj-technical-peer','generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'passed':True,'immutable_initial_peer_path':str((OUT/'review.json').relative_to(ROOT)),'immutable_initial_peer_sha256':sha(prior_raw),'EM':{'new_proposal_sha256':sha(raw),'unchanged_candidate_sha256':proposal['uncoded_items_sha256'],'computed_and_declared_authority_pages':238,'all14pairs_unchanged':True,'technical_supersessions_ledger_path':str(ledger_path.relative_to(ROOT)),'technical_supersessions_ledger_sha256':sha(ledger_raw),'all14individual_proof_hashes_verified':True,'previous_publications_immutable_declared':True},'EF383':{'new_candidate_path':str(efpath.relative_to(ROOT)),'new_candidate_sha256':sha(efraw),'old_candidate_sha256_reconstructed_exactly':sha(reconstructed),'only_byte_difference':"One occurrence of 'nine identifier glyphs' became 'eight identifier glyphs'. Inverse byte substitution exactly reproduces the previously verified artifact SHA.",'all200record_IDs_codes_texts_positions_primary_evidence_unchanged':True},'metadata_findings_resolved':2,'technical_acceptance_remains':True,'official_amendment_SourceWhole_UF_ready_human_pedagogy_claimed':False,'MF_core_cache_database_publication_modified':False};(OUT/'metadata-recheck.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(sha((OUT/'metadata-recheck.json').read_bytes()))
if __name__=='__main__':main()
